insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_07'), (select id from public.groups where slug = 'attack-on-titan' and site_id = 'anime'), 'First Steps Behind the Walls: Attack on Titan Basics', 'first-steps-behind-the-walls-attack-on-titan-basics', 'multiple_choice', '[{"question":"Who wrote and drew the whole Attack on Titan manga himself?","options":["Koyoharu Gotouge","Hiromu Arakawa","Hajime Isayama","Gege Akutami"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-manga-creator-011"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan"},{"question":"Which publisher''s monthly magazine, Bessatsu Shonen Magazine, ran Attack on Titan?","options":["Shueisha","Kodansha","Shogakukan","Square Enix"],"correct":1,"fun_fact":"The magazine launched with the first chapter.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-magazine-publisher-013"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan"},{"question":"The Attack on Titan chapters were collected in how many volumes?","options":["20","28","41","34"],"correct":3,"fun_fact":"The story closed after 139 chapters.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-volume-count-014"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan"},{"question":"The Attack on Titan manga finished at which chapter number?","options":["139","100","120","156"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-chapter-count-015"],"source_url":"https://ja.wikipedia.org/wiki/%E9%80%B2%E6%92%83%E3%81%AE%E5%B7%A8%E4%BA%BA"},{"question":"In which year did the Attack on Titan anime open with a 25-episode first season?","options":["2013","2010","2011","2015"],"correct":0,"fun_fact"