insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_06'), (select id from public.groups where slug = 'demon-slayer' and site_id = 'anime'), 'Demon Slayer Starter Kit: Corps Basics', 'demon-slayer-starter-kit-corps-basics', 'multiple_choice', '[{"question":"Who both wrote and drew the Demon Slayer manga?","options":["Gege Akutami","Koyoharu Gotouge","Masashi Kishimoto","Tite Kubo"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["demon-slayer-creator-003"],"source_url":"https://en.wikipedia.org/wiki/Demon_Slayer:_Kimetsu_no_Yaiba"},{"question":"The Japanese title Kimetsu no Yaiba can be roughly translated as what?","options":["Sword of the Night Hunters","Edge of the Crimson Moon","Blade of Demon Destruction","Slayers of the Mountain"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["demon-slayer-title-forms-002"],"source_url":"https://en.wikipedia.org/wiki/Demon_Slayer:_Kimetsu_no_Yaiba"},{"question":"The Demon Slayer manga was gathered into how many collected volumes?","options":["23","12","31","40"],"correct":0,"fun_fact":"Shueisha released the volumes between June 2016 and December 2020.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["demon-slayer-volumes-005"],"source_url":"https://en.wikipedia.org/wiki/Demon_Slayer:_Kimetsu_no_Yaiba"},{"question":"Which studio produced the Demon Slayer TV anime?","options":["Ufotable","MAPPA","Wit Studio","Bones"],"correct":0,"fun_fact":"Haruo Sotozaki is the director.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["demon-slayer-studio-director-007"],"source_url":"https://en.wikipedia.org/wiki/Demon_Slayer:_Kimetsu_no_Yaiba_(TV_series)"},{"question":"In which year did the Demon Slayer TV anime launch?","options":["2016","2017","2021","2019"],"correct