insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_24'), (select id from public.groups where slug = 'evangelion' and site_id = 'anime'), 'From Episode 26 to Rebuild: Evangelion Odds and Ends', 'from-episode-26-to-rebuild-evangelion-odds-and-ends', 'multiple_choice', '[{"question":"Readers of which magazine voted the 1995 series top Best Loved Series at the Anime Grand Prix?","options":["Newtype","Nakayoshi","Weekly Shōnen Jump","Animage"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-animage-grand-prix-011"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"In which two years did the 1995 series place first as Best Loved Series?","options":["1995 and 1996","1996 and 1997","1997 and 1998","1996 and 1998"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-animage-grand-prix-011"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"In which year did Hideaki Anno begin shaping the project?","options":["1989","1993","1995","1997"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-production-start-010"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"On which date did the final episode of the 1995 series air?","options":["October 4, 1995","July 19, 1997","June 21, 2019","March 27, 1996"],"correct":3,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-broadcast-run-003"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"The End of Evangelion is a new take on which part of the 1995 series?","options":["The last two episodes","The first two episodes","The middle episodes","Every episode"],"correct":0,