insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_26'), (select id from public.groups where slug = 'kaiju-no-8' and site_id = 'anime'), 'Combat Power Check: Kaiju No. 8 True or False', 'combat-power-check-kaiju-no-8-true-or-false', 'true_false', '[{"question":"Naoya Matsumoto is both writer and artist of the manga, which ran on Shueisha''s Shōnen Jump+ from July 3, 2020 until July 18, 2025.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaiju-no-8-author-run-002"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaiju_No._8_chapters"},{"question":"The manga closed after 129 chapters collected in 26 volumes, with the final book reaching Japanese shops on September 4, 2025.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaiju-no-8-manga-completion-003"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaiju_No._8_chapters"},{"question":"The manga closed after 129 chapters collected in 16 volumes, with the final book reaching Japanese shops on September 4, 2025.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaiju-no-8-manga-completion-003"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaiju_No._8_chapters"},{"question":"Officers fight in powered suits built from kaiju remains, and each suit shows a combat power percentage that tops out at 200.","correct":false,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["kaiju-no-8-setting-powered-suits-009"],"source_url":"https://en.wikipedia.org/wiki/Kaiju_No._8"},{"question":"Officers fight in powered suits built from kaiju remains, and each suit shows a combat power percentage that tops out at 100.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["kaiju-no-8-setting-powered-suits-009"],"source_url":"https://en.wikipedia.org/wiki/Kaiju_No._8"},{"question":"Naoya Matsumoto is both writer and artist of the manga, which ran on Shueisha''s Weekly Shōnen Jump from July 3, 2020 until July 18, 2025.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaiju-no-8-author-run-002"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaiju_No._8_chapters"},{"question":"Matsumoto drew on Japanese tokusatsu shows, above all the Ultraman series.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaiju-no-8-tokusatsu-influence-010"],"source_url":"https://en.wikipedia.org/wiki/Kaiju_No._8"},{"question":"The manga took the 2021 Next Manga Award for web manga and won an Eisner Award the year after.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaiju-no-8-awards-011"],"source_url":"https://en.wikipedia.org/wiki/Kaiju_No._8"},{"question":"The manga took the 2021 Next Manga Award for web manga and was shortlisted for an Eisner Award the year after.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaiju-no-8-awards-011"],"source_url":"https://en.wikipedia.org/wiki/Kaiju_No._8"},{"question":"Matsumoto drew on Japanese tokusatsu shows, above all the Kamen Rider series.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaiju-no-8-tokusatsu-influence-010"],"source_url":"https://en.wikipedia.org/wiki/Kaiju_No._8"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
