insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_04'), (select id from public.groups where slug = 'naruto' and site_id = 'anime'), 'Naruto From Zero: A Friendly Start', 'naruto-from-zero-the-friendly-start', 'multiple_choice', '[{"question":"Who wrote and drew the Naruto manga?","options":["Eiichiro Oda","Masashi Kishimoto","Tite Kubo","Hajime Isayama"],"correct":1,"fun_fact":"Masashi Kishimoto both wrote and drew the Naruto manga himself.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-authors-002"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"In which magazine did the Naruto manga run?","options":["Weekly Shonen Jump","Weekly Shonen Magazine","Monthly Shonen Gangan","Weekly Young Jump"],"correct":0,"fun_fact":"It ran in Weekly Shonen Jump, published by Shueisha.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-serialization-003"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"The Naruto manga was collected into how many volumes?","options":["60","66","72","80"],"correct":2,"fun_fact":"The manga closed with 700 chapters gathered into 72 collected volumes.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-manga-size-005"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Which studio animated the Naruto TV anime?","options":["Madhouse","Bones","MAPPA","Studio Pierrot"],"correct":3,"fun_fact":"Studio Pierrot made Naruto and Naruto: Shippuden, directed by Hayato Date.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"How many episodes does the first TV series, simply called Naruto, have?","options":["135","500","220","720"],"correct":2,"fun_fact":"The second series, Shippuden, adds 500 more, for 720 episodes in total.","kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006","naruto-episode-total-008"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"In which year did the Naruto manga start in Weekly Shonen Jump?","options":["1997","1999","2002","2004"],"correct":1,"fun_fact":"It ran for about fifteen years, until mid November 2014.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-manga-run-004"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"In which year did the first Naruto anime begin airing in Japan?","options":["1999","2004","2007","2002"],"correct":3,"fun_fact":"Naruto, the first series, has 220 episodes and aired from 2002 to 2007.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Of the first anime''s 220 episodes, how many are original stories made only for TV?","options":["85","135","45","100"],"correct":0,"fun_fact":"The first 135 episodes follow the manga, and the other 85 are stories made only for television.","kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["naruto-original-episodes-023"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Which of these titles belongs to the Naruto franchise?","options":["Bleach: Thousand-Year Blood War","Black Clover","Boruto: Two Blue Vortex","Fairy Tail"],"correct":2,"fun_fact":"The franchise includes Naruto, Naruto: Shippuden and the Boruto titles.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-franchise-009"],"source_url":"https://naruto-official.com/en"},{"question":"The manga is split in two parts. Which volumes make up Part II?","options":["28 to 72","1 to 27","20 to 60","30 to 72"],"correct":0,"fun_fact":"Volumes 1 to 27 follow Naruto as a child, and volumes 28 to 72 follow him as a teenager.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-part-one-volumes-025"],"source_url":"https://en.wikipedia.org/wiki/Naruto"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_04'), (select id from public.groups where slug = 'naruto' and site_id = 'anime'), 'Naruto: Openings, Endings and the Studio', 'naruto-openings-endings-and-the-studio', 'multiple_choice', '[{"question":"Which song opened Naruto: Shippuden for its first thirty episodes?","options":["Haruka Kanata","Blue Bird","Closer","Hero''s Come Back!!"],"correct":3,"fun_fact":"It opened Shippuden from episode 1 to 30.","kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-first-shippuden-opening-027"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Which group performed Hero''s Come Back!!, the first Shippuden opening?","options":["nobodyknows+","HOUND DOG","FLOW","Ikimonogakari"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-first-shippuden-opening-027"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Which artist performed the very first Naruto opening, used for episodes 1 to 25?","options":["HOUND DOG","FLOW","Sambomaster","Snowkel"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-op-part-one-018"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Which singer performed two endings of the first series, Wind and Yellow moon?","options":["Rythem","Akeboshi","Orange Range","TiA"],"correct":1,"fun_fact":"Wind opened the run of endings, and Yellow moon came much later.","kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-akeboshi-endings-028"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Which band performed the openings GO!!!, Re:member and Sign?","options":["Asian Kung-Fu Generation","Ikimonogakari","FLOW","Nico Touches the Walls"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-op-part-one-018","naruto-themes-op-part-two-019"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Which opening accompanied episodes 154 to 178 of the first series?","options":["Re:member","Namikaze Satellite","Yura Yura","No Boy, No Cry"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-op-part-one-018"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Which group performed the third ending, Viva Rock ~japanese side~?","options":["Rythem","Orange Range","Raigo","Akeboshi"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-ed-part-one-020"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Who performed the first ending of Shippuden, Nagareboshi ~Shooting Star~?","options":["supercell","Home Made Kazoku","Aqua Timez","Nico Touches the Walls"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-ed-part-two-a-021"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Who directed both Naruto TV series?","options":["Tetsuro Araki","Shinichiro Watanabe","Hayato Date","Hiroyuki Imaishi"],"correct":2,"fun_fact":"Hayato Date is the director of both Naruto TV series from Studio Pierrot.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006","naruto-tv-shippuden-007"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Who designed the characters for the Naruto anime?","options":["Masashi Kishimoto","Yoshiyuki Sadamoto","Tetsuya Nishio","Hirohiko Araki"],"correct":2,"fun_fact":"Tetsuya Nishio designed the characters for the anime because Kishimoto himself asked for him.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-character-designer-024"],"source_url":"https://en.wikipedia.org/wiki/Naruto"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_04'), (select id from public.groups where slug = 'naruto' and site_id = 'anime'), 'Naruto True or False: Ninja Edition', 'naruto-true-or-false-ninja-edition', 'true_false', '[{"question":"Masashi Kishimoto both wrote and drew the Naruto manga.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-authors-002"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"The Naruto manga closed with 800 chapters gathered into 72 collected volumes.","correct":false,"fun_fact":"The manga closed with 700 chapters.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-manga-size-005"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Counting both series, the Naruto anime adds up to 720 episodes.","correct":true,"fun_fact":"That is 220 episodes of Naruto and 500 of Shippuden.","kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-episode-total-008"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Naruto: Shippuden has 220 episodes.","correct":false,"fun_fact":"Shippuden has 500 episodes. The first series has 220.","kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-shippuden-007"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Of the first anime''s 220 episodes, 135 follow the manga and the other 85 are original stories.","correct":true,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["naruto-original-episodes-023"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Madhouse is the studio that made the Naruto anime.","correct":false,"fun_fact":"Studio Pierrot made Naruto and Naruto: Shippuden.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Tetsuya Nishio designed the characters for the Naruto anime.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-character-designer-024"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Naruto: Shippuden opened with Hero''s Come Back!! by nobodyknows+.","correct":true,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-first-shippuden-opening-027"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Singer Akeboshi performed two openings of the first series.","correct":false,"fun_fact":"Akeboshi sang two endings, Wind and Yellow moon.","kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-akeboshi-endings-028"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Volumes 1 to 27 of the manga follow Naruto as a teenager.","correct":false,"fun_fact":"Volumes 1 to 27 follow Naruto as a child. The teenage years fill volumes 28 to 72.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-part-one-volumes-025"],"source_url":"https://en.wikipedia.org/wiki/Naruto"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
