 9, 2026","July 22, 2025","July 23, 2025","August 18, 2020"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["omniscient-readers-viewpoint-english-licence-009"],"source_url":"https://en.wikipedia.org/wiki/Omniscient_Reader%27s_Viewpoint"},{"question":"Who is credited as the artist of the webtoon?","options":["singNsong","Kim Byung-woo","UMI","Sleepy-C"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["omniscient-readers-viewpoint-credited-authors-003"],"source_url":"https://en.wikipedia.org/wiki/Omniscient_Reader%27s_Viewpoint"},{"question":"On which platform''s list were the prologue and the first two episodes posted on the same day for English readers?","options":["Line Webtoon","Naver Webtoon","Munpia","A.Tempo Media"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["omniscient-readers-viewpoint-english-webtoon-007"],"source_url":"https://en.wikipedia.org/wiki/Omniscient_Reader%27s_Viewpoint"},{"question":"On which date did the live-action film open in South Korean cinemas?","options":["July 22, 2025","May 26, 2020","July 23, 2025","December 22, 2020"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["omniscient-readers-viewpoint-film-release-011"],"source_url":"https://en.wikipedia.org/wiki/Omniscient_Reader:_The_Prophecy"},{"question":"Which episode number was labeled the season finale of the webtoon?","options":["300","310","312","311"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["omniscient-readers-viewpoint-season-one-finale-008"],"source_url":"https://comic.naver.com/webtoon/list?titleId=747269"}]'::jsonb, 'medium', 'published', 9, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_c