:15,"scope":"both"},"fact_ids":["one-piece-arcs-1-007"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"Which of these arcs exists only in the anime?","options":["Warship Island","Orange Town","Loguetown","Drum Island"],"correct":0,"kind":"arc","spoiler":{"arc":15,"scope":"both"},"fact_ids":["one-piece-arcs-1-007"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"Which arc fills chapters 101 to 105 and episodes 62 to 63?","options":["Whiskey Peak","Little Garden","Reverse Mountain / Into the Grand Line","Drum Island"],"correct":2,"kind":"arc","spoiler":{"arc":15,"scope":"both"},"fact_ids":["one-piece-arcs-1-007"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"Which arc fills episodes 78 to 91?","options":["Little Garden","Whiskey Peak","Alabasta","Drum Island"],"correct":3,"kind":"arc","spoiler":{"arc":15,"scope":"both"},"fact_ids":["one-piece-arcs-1-007"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"Which arc fills chapters 115 to 129?","options":["Little Garden","Whiskey Peak","Drum Island","Alabasta"],"correct":0,"kind":"arc","spoiler":{"arc":15,"scope":"both"},"fact_ids":["one-piece-arcs-1-007"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"}]'::jsonb, 'hard', 'published', 10, 'anime', 15, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_02'), (select id from public.groups where slug = 'one-piece' and site_id = 'anime'), 'Pirate''s Honor: One Piece True or False', 'pirates-honor-one-piece-true-or-false', 'true_false', '[{"question":"Eiichiro Oda is the one person behind both the writing and the drawing of the One Piece manga.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"Shueisha has run the manga in Weekly Shōnen Jump since the summer of 1999.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"By the start of July 2026 Shueisha had put out 115 collected volumes of the manga.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-manga-volumes-004"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"The anime began on Fuji Television in the autumn of 1997.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["one-piece-anime-studio-005"],"source_url":"https://en.wikipedia.org/wiki/One_Piece_(1999_TV_series)"},{"question":"The anime had reached 1180 episodes by late September 2026.","correct":true,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["one-piece-anime-size-006"],"source_url":"https://en.wikipedia.org/wiki/List_of_One_Piece_episodes"},{"question":"Guinness World Records recognized Oda in 2015 and 2022 for the longest running anime.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-guinness-record-017"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{