insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_02'), (select id from public.groups where slug = 'one-piece' and site_id = 'anime'), 'Raising the Flag: One Piece Basics', 'raising-the-flag-one-piece-basics', 'multiple_choice', '[{"question":"Who is the one person behind both the writing and the drawing of the One Piece manga?","options":["Kohei Tanaka","Shiro Hamaguchi","Eiichiro Oda","Tatsuya Endo"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"In which year did the One Piece manga start in Weekly Shōnen Jump?","options":["1997","1995","1999","2001"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"How many collected volumes of the manga had been released by July 2026?","options":["99","108","125","115"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-manga-volumes-004"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"Which studio makes the One Piece TV anime?","options":["Madhouse","Toei Animation","MAPPA","CloverWorks"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["one-piece-anime-studio-005"],"source_url":"https://en.wikipedia.org/wiki/One_Piece_(1999_TV_series)"},{"question":"On which channel did the One Piece TV anime begin in 1999?","options":["TV Tokyo","Fuji Television","Nippon Television","NHK General TV"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["one-piece-anime-studio-005"],"source_url":"https://en.wikipedia.org/wiki/One_Piece_(1999_TV_series)"},{"question":"About how many copies of the man