insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_28'), (select id from public.groups where slug = 'one-punch-man' and site_id = 'anime'), 'Punch or Bluff: One-Punch Man True or False', 'punch-or-bluff-one-punch-man-true-or-false', 'true_false', '[{"question":"One came up with the story, and Yusuke Murata redrew it for the published manga.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-creators-002"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"},{"question":"Yusuke Murata came up with the story, and One redrew it for the published manga.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-creators-002"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"},{"question":"The story began in 2009 as a webcomic that One put online himself, before any publisher was involved.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-webcomic-start-003"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"},{"question":"The story began in 2015 as a webcomic that One put online himself.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-webcomic-start-003"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"},{"question":"Murata''s redrawn version has appeared on Shueisha''s Tonari no Young Jump site since 14 June 2012.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-remake-magazine-004"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"},{"question":"The remake had reached 27 collected volumes by early July 2026.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-volume-count-005"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"},{"question":"The remake had reached 37 collected volumes by early July 2026.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-volume-count-005"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"},{"question":"Murata''s redrawn version has appeared on Shueisha''s Weekly Shōnen Jump site since 14 June 2012.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-remake-magazine-004"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"},{"question":"Season 1 was animated by Madhouse under director Shingo Natsume and ran for 12 episodes from 5 October to 21 December 2015.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["one-punch-man-anime-season-one-007"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man_season_1"},{"question":"In 2017 the manga took home both the Eisner Award and the seinen category prize at Manga Barcelona.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-punch-man-award-2017-011"],"source_url":"https://en.wikipedia.org/wiki/One-Punch_Man"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
