-- DRAFTS: a rehearsal file (every draft fact and row). Never apply it to production.
-- L07-K2-catalogue.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   150 published quizzes (1449 questions) on the anime site, signed by the Team creators; the spoiler level is computed from the question tags.
-- Needs:  L02, L04, 002d, 011.
-- Verify: select count(*) from public.quizzes where site_id = 'anime' and status = 'published';   expect 150
-- Undo:   L07-K2-catalogue.rollback.sql (refused once a quiz has been played).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quizzes' and column_name = 'spoiler_arc_ord') then
    raise exception 'L07: quizzes.spoiler_arc_ord is missing (apply 011 first)';
  end if;
end $o1l$;

do $o1l$ begin
  if (select count(*) from public.profiles where username in ('oq_creator_21', 'oq_creator_07', 'oq_creator_11', 'oq_creator_22', 'oq_creator_12', 'oq_creator_23', 'oq_creator_13', 'oq_creator_01', 'oq_creator_06', 'oq_creator_08', 'oq_creator_24', 'oq_creator_14', 'oq_creator_15', 'oq_creator_16', 'oq_creator_17', 'oq_creator_18', 'oq_creator_05', 'oq_creator_25', 'oq_creator_26', 'oq_creator_09', 'oq_creator_04', 'oq_creator_27', 'oq_creator_02', 'oq_creator_28', 'oq_creator_19', 'oq_creator_29', 'oq_creator_10', 'oq_creator_03', 'oq_creator_20', 'oq_creator_30')) <> 30 then
    raise exception 'L07: a Team creator has no profile (apply L02 first)';
  end if;
end $o1l$;

do $o1l$ begin
  if (select count(*) from public.groups where site_id = 'anime' and slug in ('apothecary-diaries', 'attack-on-titan', 'bleach', 'blue-lock', 'chainsaw-man', 'cowboy-bebop', 'dandadan', 'death-note', 'demon-slayer', 'dragon-ball', 'evangelion', 'frieren', 'fullmetal-alchemist', 'haikyu', 'hunter-x-hunter', 'jojo', 'jujutsu-kaisen', 'kagurabachi', 'kaiju-no-8', 'my-hero-academia', 'naruto', 'omniscient-readers-viewpoint', 'one-piece', 'one-punch-man', 'oshi-no-ko', 'sailor-moon', 'solo-leveling', 'spy-x-family', 'tower-of-god', 'vinland-saga', 'anime-mix')) <> 31 then
    raise exception 'L07: the series groups are missing (apply L04 first)';
  end if;
end $o1l$;






















































































































































